<script lang="ts">import UnavailableChart from './UnavailableChart.svelte'; import type { Cluster, Unavailable } from './types'; import { percent } from './types'; let { data }: { data: Cluster[] | Unavailable } = $props();</script><figure class="chart"><h3>Synergy clusters</h3>{#if !Array.isArray(data)}<UnavailableChart reason={data.reason}/>{:else}{#each data as cluster}<div class="cluster"><div class="score-head"><strong>{cluster.name}</strong><span class="mono">{percent(cluster.strength)}</span></div><svg viewBox="0 0 320 16" role="img" aria-label={`${cluster.name}: ${percent(cluster.strength)} strength`}><rect x="0" y="4" width="320" height="8" class="track"/><rect x="0" y="4" width={cluster.strength*320} height="8" class="data-bar"/></svg><p class="card-names">{cluster.cards.map(c=>c.name).join(' · ')}</p></div>{:else}<p>No synergy clusters identified.</p>{/each}{/if}</figure>